import java.util.SortedMap;
import java.util.TreeMap;
import java.util.zip.CRC32;

public class ConsistentHashRing {
    private final TreeMap<Long, String> ring = new TreeMap<>();
    private final int virtualCount; // 每物理节点的虚拟节点数

    public ConsistentHashRing(int virtualCount) {
        this.virtualCount = virtualCount;
    }

    public void addNode(String node) {
        for (int i = 0; i < virtualCount; i++) {
            long h = hash(node + "#" + i);
            ring.put(h, node);
        }
    }

    public void removeNode(String node) {
        for (int i = 0; i < virtualCount; i++) {
            ring.remove(hash(node + "#" + i));
        }
    }

    /** 顺时针找到第一个 >= h 的节点；超过环尾则回到环首 */
    public String route(String key) {
        long h = hash(key);
        SortedMap<Long, String> tail = ring.tailMap(h);
        Long target = tail.isEmpty() ? ring.firstKey() : tail.firstKey();
        return ring.get(target);
    }

    private long hash(String s) {
        CRC32 crc = new CRC32();
        crc.update(s.getBytes());
        return crc.getValue();
    }

    // 验证：3 个物理节点、各 200 虚拟节点，随机 10 万个 key 的分布
    public static void main(String[] args) {
        ConsistentHashRing ring = new ConsistentHashRing(200);
        ring.addNode("node-A");
        ring.addNode("node-B");
        ring.addNode("node-C");

        int[] count = new int[3];
        String[] nodes = {"node-A", "node-B", "node-C"};
        for (int i = 0; i < 100_000; i++) {
            String owner = ring.route("key-" + i);
            for (int j = 0; j < 3; j++) {
                if (nodes[j].equals(owner)) { count[j]++; break; }
            }
        }
        System.out.printf("A=%d B=%d C=%d%n", count[0], count[1], count[2]);
    }
}
